--
-- Table structure for table `course_section`
--

DROP TABLE IF EXISTS `course_section`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_section` (
  `CRN` int NOT NULL,
  `course_ID` int NOT NULL,
  `section_No` int NOT NULL,
  `faculty_ID` int NOT NULL,
  `time_Slot_ID` int NOT NULL,
  `lecture_ID` int DEFAULT NULL,
  `lab_ID` int DEFAULT NULL,
  `semester_ID` int NOT NULL,
  `available_Seats` int NOT NULL,
  PRIMARY KEY (`CRN`),
  UNIQUE KEY `uq_Course_Section_CRN_course_semester` (`CRN`,`course_ID`,`semester_ID`),
  UNIQUE KEY `uq_Course_Section_CRN_semester` (`CRN`,`semester_ID`),
  UNIQUE KEY `uq_Course_Section_CRN_course` (`CRN`,`course_ID`),
  UNIQUE KEY `uq_Course_Section_CRN_faculty` (`CRN`,`faculty_ID`),
  UNIQUE KEY `uq_Course_Section_course_semester_section` (`course_ID`,`semester_ID`,`section_No`),
  KEY `faculty_ID` (`faculty_ID`),
  KEY `lecture_ID` (`lecture_ID`),
  KEY `lab_ID` (`lab_ID`),
  KEY `time_Slot_ID` (`time_Slot_ID`),
  KEY `semester_ID` (`semester_ID`),
  CONSTRAINT `course_section_ibfk_1` FOREIGN KEY (`course_ID`) REFERENCES `course` (`course_ID`),
  CONSTRAINT `course_section_ibfk_2` FOREIGN KEY (`faculty_ID`) REFERENCES `faculty` (`faculty_ID`),
  CONSTRAINT `course_section_ibfk_3` FOREIGN KEY (`lecture_ID`) REFERENCES `lecture` (`lecture_ID`),
  CONSTRAINT `course_section_ibfk_4` FOREIGN KEY (`lab_ID`) REFERENCES `lab` (`lab_ID`),
  CONSTRAINT `course_section_ibfk_5` FOREIGN KEY (`time_Slot_ID`) REFERENCES `time_slot` (`time_Slot_ID`),
  CONSTRAINT `course_section_ibfk_6` FOREIGN KEY (`semester_ID`) REFERENCES `semester` (`semester_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

