  `CRN` int NOT NULL,
  `course_ID` int NOT NULL,
  `semester_ID` int NOT NULL,
  `Grade` varchar(5) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`student_ID`,`CRN`),
