  CONSTRAINT `student_history_ibfk_2` FOREIGN KEY (`CRN`) REFERENCES `course_section` (`CRN`),
  CONSTRAINT `student_history_ibfk_3` FOREIGN KEY (`course_ID`) REFERENCES `course` (`course_ID`),
  CONSTRAINT `student_history_ibfk_4` FOREIGN KEY (`semester_ID`) REFERENCES `semester` (`semester_ID`),
  CONSTRAINT `student_history_ibfk_5` FOREIGN KEY (`CRN`, `course_ID`, `semester_ID`) REFERENCES `course_section` (`CRN`, `course_ID`, `semester_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
