DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `user_ID` int NOT NULL,
  `first_Name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `middle_Name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `last_Name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `gender` enum('Male','Female','Other') COLLATE utf8mb4_general_ci NOT NULL,
  `DOB` date NOT NULL,
  `street` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `city` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `state` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `zip_Code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `user_Type` enum('Student','Faculty','Admin','StatStaff') COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`user_ID`),
  UNIQUE KEY `uq_User_ID_user_Type` (`user_ID`,`user_Type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
